import { supabase } from './client'
import type { TenantManifest } from '@/entities/tenant/types'
import { defaultTenantManifest } from '@/app/config/manifest.default'

export type TenantSummary = {
  id: string
  slug: string
  name: string
  status?: string | null
  created_at?: string | null
}

export const tenantsService = {
  async fetchManifest(slug: string): Promise<TenantManifest | null> {
    const { data, error } = await supabase
      .from('tenants')
      .select('*')
      .eq('slug', slug)
      .maybeSingle()
    if (error) {
      console.warn('[tenants] fetchManifest failed:', error.message)
      return null
    }
    if (!data) return null
    const row = data as Record<string, unknown>
    // DB row only has a few columns (id, slug, name, status, branding jsonb, ...).
    // Merge with defaults so manifest shape (localization, branding.lightTheme, enabledApps, ...) is always complete.
    return {
      ...defaultTenantManifest,
      ...(row as Partial<TenantManifest>),
      tenantId: (row.id as string) ?? (row.tenantId as string) ?? defaultTenantManifest.tenantId,
      slug: (row.slug as string) ?? defaultTenantManifest.slug,
      name: (row.name as string) ?? defaultTenantManifest.name,
      branding: { ...defaultTenantManifest.branding, ...((row.branding as object) ?? {}) },
      localization: { ...defaultTenantManifest.localization, ...((row.localization as object) ?? {}) },
    }
  },

  async ensureTenant(input: { slug: string; name: string }): Promise<TenantSummary | null> {
    const existing = await supabase
      .from('tenants')
      .select('id, slug, name, status, created_at')
      .eq('slug', input.slug)
      .maybeSingle()
    if (existing.data) return existing.data as TenantSummary
    const { data, error } = await supabase
      .from('tenants')
      .insert({ slug: input.slug, name: input.name, status: 'active' })
      .select('id, slug, name, status, created_at')
      .single()
    if (error) {
      console.warn('[tenants] ensureTenant failed:', error.message)
      return null
    }
    return data as TenantSummary
  },

  async listAll(): Promise<TenantSummary[]> {
    const { data, error } = await supabase
      .from('tenants')
      .select('id, slug, name, status, created_at')
      .order('created_at', { ascending: false })
    if (error) {
      console.warn('[tenants] listAll failed:', error.message)
      return []
    }
    return (data ?? []) as TenantSummary[]
  },

  async create(input: { slug: string; name: string }): Promise<TenantSummary | null> {
    const { data, error } = await supabase
      .from('tenants')
      .insert({ slug: input.slug, name: input.name, status: 'active' })
      .select('id, slug, name, status, created_at')
      .single()
    if (error) {
      console.error('[tenants] create failed:', error.message)
      throw error
    }
    return data as TenantSummary
  },


  async updateStatus(id: string, status: 'active' | 'suspended' | 'trial'): Promise<void> {
    const { error } = await supabase.from('tenants').update({ status }).eq('id', id)
    if (error) throw error
  },
}
